package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamOriginTradBank2 {
    private const val T = "නර්තනයේ මූලාරම්භය, ඓතිහාසික විකාශනය හා සම්ප්‍රදායන්"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ශ්‍රී ලංකාවේ නර්තන ඉතිහාසය හැදෑරීමේදී ශිලා ලේඛන හා ගල් කැටයම් වැදගත් වන්නේ කුමන හේතුවක් නිසාද?", "එකල පැවති නර්තන ඉරියව් හා වාද්‍ය භාණ්ඩ හඳුනාගැනීමට", "නූතන වේදිකා රංග ආලෝක පද්ධති සැකසීමට", "බටහිර සම්භාව්‍ය බැලේ න්‍යායන් සසඳා බැලීමට", "විදේශීය සංගීත ප්‍රස්තාර ලියා තබා ගැනීමට", "සඳකඩපහණ, ඇම්බැක්කේ සහ යාපහුව කැටයම් ඉතිහාසයේ ස්ථිර සාධක සපයයි."),
        q("අනුරාධපුර යුගයේ සමාජයෙහි රාජකීය උත්සව හා සංස්කෘතික පෙරහැරවලට නර්තනය එක් වූ බව සඳහන් වන වංශ කතාව කුමක්ද?", "මහාවංශය", "රාජාවලිය පමණි", "මන්දාරම් පුර පුවත පමණි", "නිකාය සංග්‍රහය පමණි", "මහාවංශයේ දේවානම්පියතිස්ස සහ දුටුගැමුණු රජ සමයන්හි තූර්ය නාද හා නැටුම් ගැන දැක්වේ."),
        q("ගැමි කාන්තාවන් විසින් දිය නාන තොටුපළේ සිට කළ පිරුණු පසු ප්‍රීතියෙන් ගමන් ගන්නා ආකාරය දැක්වෙන නැටුම කුමක්ද?", "කළගෙඩි නැටුම", "කුලු නැටුම", "වන්නම් නැටුම", "සළු පාලිය", "කළ උඩ දැමීම, ඉඟටියේ තැබීම හා රවුම් කරකැවීම් කළගෙඩි නැටුමේ ප්‍රධාන ලක්ෂණ වේ."),
        q("කළගෙඩි නැටුමේදී ශිල්පිනියන් කළගෙඩි තුළින් ජලය හා සුළඟ හා බැඳුණු ශබ්දයක් උපදවන්නේ කෙසේද?", "කළ කටට පිඹීමෙන් හා හිස් කළ තට්ටු කිරීමෙන්", "කළගෙඩි බිම දමා බිඳීමෙන්", "කළගෙඩි තුළ ගිනි දැල්වීමෙන්", "රබන් පද වේගයෙන් වැයීමෙන්", "හිස් කළගෙඩිවල මුවට පිඹීමෙන් මිහිරි නාදයක් නිපදවීම කළගෙඩි නැටුමේ විශේෂත්වයකි."),
        q("ලී කෙළි නැටුම ඉදිරිපත් කිරීමේදී පෙරමුණ ගන්නා ගායකයා හෝ කණ්ඩායම් නායකයා කවි ගායනා කරන විට අනෙක් අය සිදු කරන්නේ කුමක්ද?", "කවි පදය පුනරුච්චාරණය කරමින් ලී කෙළි ගසමින් නැටීම", "බිම වාඩි වී නිහඬව සිටීම", "වේදිකාවෙන් පිටතට යාම", "ලී කෙළි ඉවතට විසි කිරීම", "නායකයා ගයන කවියට අනුව තාලයට ලී කෝටු ගැටීම හා චලන සිදු කරයි."),
        q("ගොයම් නැටුමේදී ප්‍රධාන වශයෙන් නිරූපණය කෙරෙන කෘෂිකාර්මික කාර්යයන් මොනවාද?", "පැළ සිටුවීම, ගොයම් කැපීම සහ මිටි බැඳීම", "හේන් ගොවිතැනේ දඬු වැට බැඳීම සහ පැල් රැකීම", "වැව් අමුණු පිළිසකර කිරීම සහ ඇළ වේලි කැපීම", "පොල් කැඩීම, ලෙලි ගැසීම සහ වියළීම", "අස්වැන්න නෙළීමේදී ගොවි ලියන්ගේ එදිනෙදා චලන සෞන්දර්යාත්මකව නිරූපණය වේ."),
        q("පාරම්පරික කුලු නැටුම සඳහා භාවිත කරන 'කුල්ල' නිර්මාණය කරනු ලබන ස්වාභාවික අමුද්‍රව්‍ය මොනවාද?", "උණ බට පතුරු හා වේවැල්", "පොල් ලෙලි කෙඳි හා කිතුල් පතුරු", "මැටි හා ගල් පතුරු", "තඹ තහඩු හා ලෝහ කම්බි", "උණ පතුරුවලින් වියා වේවැල්වලින් ගැටගසන කුලු සැහැල්ලු හා ශක්තිමත් වේ."),
        q("සිංහල අවුරුදු උත්සව සමයේදී ගමේ කාන්තාවන් වට වී රබන් පද ගයමින් වාදනය කරන විශාල රබාන කුමක්ද?", "බංකු රබාන", "තබ්ලාව", "මෘදංගය", "පංජාබ් ඩෝලය", "ගිනි රස්නයෙන් රත් කොට බංකු මත තබා වයන විශාල බංකු රබාන ගැමි කලාවේ අංගයකි."),
        q("බටහිර සංගීත ආභාසය හා අප්‍රිකානු කැෆර් සංස්කෘතිය ඇසුරින් මෙරට වෙරළබඩ ජනප්‍රිය වූ නැටුම් කලාව කුමක්ද?", "කපිරිඤ්ඤා හා මංඤ්ඤා", "උඩැක්කි හා පන්තේරු", "වෙස් හා නෛයන්ඩි", "තෙල්මේ හා වඩිගපටුන", "පෘතුගීසි සමයේ පැමිණි අප්‍රිකානු සේවකයන්ගෙන් මෙම වේගවත් ජන නැටුම් බිහි විය."),
        q("ශ්‍රී ලංකාවේ නර්තන කලාව තුළ 'දේශීය හා විදේශීය' අංග අතර පවතින ප්‍රධාන වෙනස කුමක්ද?", "දේශීය නර්තනය පූජනීය ශාන්තිකර්ම හා පාරම්පරික රිද්ම මත පදනම් වීම", "දේශීය නර්තනයට කිසිදු වාද්‍ය භාණ්ඩයක් නොමැති වීම", "විදේශීය නර්තනවල රිද්මයක් නොමැති වීම", "දේශීය නර්තනයේ කිසිදු ඇඳුම් පැළඳුමක් නොමැති වීම", "අපේ සම්ප්‍රදායික නර්තනය ගැඹුරු ආධ්‍යාත්මික හා ජන ජීවිත පදනමකින් යුක්තය."),
        q("පැරණි සිංහල රජ දවස නැටුම් හා ගැයුම් පිළිබඳව සඳහන් වන 'නාටක' යන වචනයේ නිවැරදි අර්ථය කුමක්ද?", "නැටුම, ගැයුම හා රංගනය එක් වූ කලා අංගය", "පංචතූර්ය වාද්‍ය භාණ්ඩ ගබඩාව", "වෙස්මුහුණු කැපීමේ කැටයම් පන්තිය", "ගැමි කෘෂිකාර්මික කමත් උත්සවය", "පෙරදිග සාහිත්‍යයේ නාටක යනු ගායන, වාදන, නර්තන හා අභිනය ඇතුළත් සම්පූර්ණ රංගනයයි."),
        q("කඳුරට ප්‍රදේශවල වී කෙටීම හා බැඳුණු රිද්මයානුකූල ගැමි නැටුම් අංගයට නිදසුනක් කුමක්ද?", "මෝල්ගස් නැටුම හා කුලු නැටුම", "හක්ගෙඩි නැටුම", "ගිනි පෑගීම", "රිටි පැනීම", "ගැමි කාන්තාවන්ගේ එදිනෙදා වංගෙඩි මෝල්ගස් ක්‍රියාවලිය ඇසුරින් සමූහ නර්තන නිර්මාණය වී ඇත."),
        q("උඩරට නර්තන ක්ෂේත්‍රයේදී 'පහන් නැටුම' ඉදිරිපත් කරනු ලබන්නේ කුමන උපකරණයක් අතැතිවද?", "දැල්වූ පිත්තල හෝ මැටි පහන්", "විදුලි පන්දම්", "ලෝහ කඩු", "උණ බට කෝටු", "අත්ල මත දැල්වෙන පහන් තබාගෙන සමබරතාව රැකගනිමින් ඉතා සියුම් ලෙස මෙය නටනු ලැබේ."),
        q("ගැමි ජන නැටුම්වලදී 'රබන් නැටුම' සඳහා භාවිත කරන කුඩා රබාන හඳුන්වන නම කුමක්ද?", "අත් රබාන", "යක් බෙරය", "ගැටබෙරය", "දිගු දවුල", "තනි අතින් අල්ලා කරකවමින් හා අනෙක් අතින් තාලයට ගසමින් වයන්නේ අත් රබානයි."),
        q("ශ්‍රී ලංකාවේ නර්තන සම්ප්‍රදායන් හදාරන ආධුනිකයෙකු මූලිකවම අනුගමනය කළ යුතු ශාරීරික පුහුණුව කුමක්ද?", "නම්‍යශීලී බව, සමබරතාව හා දණහිස් ශක්තිය වැඩීම", "කඩු හා දඬු හරඹ පුහුණුව පමණි", "උස පැනීමේ හා දිවීමේ තරග පමණි", "ගැඹුරු ශ්වසන හා භාවනා අභ්‍යාස පමණි", "මණ්ඩි ඉරියව්ව රැකගැනීමට හා සංකීර්ණ චලන කිරීමට සිරුරේ නම්‍යශීලී බව අත්‍යවශ්‍ය වේ."),
        q("මහනුවර යුගයේ රජවරුන් විසින් කලා ශිල්පීන්ට ලබා දුන් ගෞරව නාම අතර ප්‍රමුඛ නාමයක් කුමක්ද?", "පණික්කි මුදියන්සේ හෝ මුහන්දිරම්", "අග්‍රාමාත්‍ය", "මහා විනිසුරු", "රාජ්‍ය භාණ්ඩාගාරික", "දක්ෂ නර්තන හා වාදන ශිල්පීන්ට රජු විසින් නම්බුනාම හා රන් තෑගි පිරිනමනු ලැබීය."),
        q("කඳුරට, පහතරට හා සබරගමු නර්තන සම්ප්‍රදායන් අතරින් 'ලැසි ගමන් හා මෘදු වක්‍ර චලන' බහුලව දැකිය හැකි සම්ප්‍රදාය කුමක්ද?", "සබරගමු නර්තන සම්ප්‍රදාය", "පහතරට තෙල්මේ සම්ප්‍රදාය", "උඩරට කස නැටුම් සම්ප්‍රදාය", "කථකලි යුද නැටුම", "සබරගමු නැටුමේ චලන සෞම්‍ය හා කැරකැවෙන සුළු ස්වභාවයකින් යුක්තය."),
        q("පහතරට නර්තන සම්ප්‍රදායේ ආවේණික ලක්ෂණයක් වන 'ගමන් තාලය' හා 'උස පැනුම්' මඟින් පෙන්නුම් කරන්නේ කුමක්ද?", "වෙරළබඩ සුළඟ හා රළ පෙළෙහි ප්‍රබල චලන", "මධ්‍යම කඳුකරයේ හිම පතනය", "කාන්තාර වැලි කුණාටු", "විදේශීය හමුදා පෙළපාලි", "පහතරට නර්තනයේ ජවසම්පන්න බව හා හඬ නැඟෙන පාද චලන ප්‍රාදේශීය පරිසරය හා බැඳී පවතී."),
        q("උඩරට නර්තන සම්ප්‍රදායේ ආභාසය ගත් චලන රටාවන් ස්වභාවධර්මයේ කුමන සතුන්ගෙන් අනුකරණය කර ඇත්ද?", "ඇතා, අශ්වයා, මොනරා, සිංහයා හා උකුස්සා", "කැන්ගරුවා සහ පෙන්ගුවින්", "හිම වලසා සහ සීල් මත්ස්‍යයා", "ඔටුවා සහ ජිරාෆ්", "වන්නම් නිර්මාණයේදී ශ්‍රී ලංකාවේ හා පරිසරයේ සිටින සතුන්ගේ ගමන් රටා අනුකරණය කර ඇත."),
        q("ගැමි ජනතාව එක්රැස් වී මල් පූජාවන් සමඟ ඉදිරිපත් කරන ගෞරවනීය නැටුම කුමක්ද?", "මල් නැටුම", "සන්නි නැටුම", "වඩිග පටුන", "කෝලම් නැටුම", "මල් වට්ටි අතැතිව බුදුන් හෝ දෙවියන් උදෙසා ලැසි ගමනින් මල් නැටුම ඉදිරිපත් කෙරේ."),
        q("නර්තනය සඳහා 'කලාලය' හෝ 'මණ්ඩපය' පිළියෙළ කිරීමේදී පැරැන්නන් සැලකිලිමත් වූ ප්‍රධාන කරුණ කුමක්ද?", "පිරිසිදු බව, ආලෝකය හා පූජනීය සැරසිලි", "වර්ණ කඩදාසි මල් හා රෙදි තොරණ එල්ලීම", "වේදිකාව වටා සම්පූර්ණ බිත්ති ඉදි කිරීම", "ප්‍රේක්ෂකයන් හා ශිල්පීන් අතර තිරයක් ඇදීම", "ගොක් කොළ, කෙසෙල් කඳන් හා පන්දම් ආලෝකයෙන් සාම්ප්‍රදායික රඟමඬල සැරසීය."),
        q("නර්තන ඉතිහාසයේදී 'කළ එළි බැසීම' යන සංස්කෘතික චාරිත්‍රය සිදු කරන්නේ කුමන අවස්ථාවකදීද?", "ශිෂ්‍යයෙකු මූලික පුහුණුව නිම කර ප්‍රථම ප්‍රසිද්ධ රංගනය ඉදිරිපත් කරන විට", "නැටුමෙන් සම්පූර්ණයෙන් විශ්‍රාම ගන්නා විට", "බෙරයක් මිලදී ගන්නා විට", "පොතක් මුද්‍රණය කරන විට", "ගුරුවරයාගේ අධීක්ෂණය යටතේ සමාජය ඉදිරියේ තම දක්ෂතා එළිදැක්වීම මෙම උත්සවයයි."),
        q("පැරණි ලංකාවේ 'තේවා නැටුම' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "දළදා මාලිගාව හා දේවාලවල පවත්වන පූජා නැටුම්", "ගැමි සොකරි රඟමඬලේ ඉදිරිපත් කරන විනෝද නැටුම්", "කමතේ අස්වැන්න නෙළා අවසානයේ නටන තරග නැටුම්", "නව නර්තන ශාලාවක් විවෘත කිරීමේ සාද නැටුම්", "දිනපතා උදේ, දහවල් හා සවස දෙවියන් හා දළදා වහන්සේ උදෙසා තේවාවන් සිදු කෙරේ."),
        q("ගැමි නැටුම් අතර 'පන්දම් පාලිය' ක්‍රියාත්මක කරනු ලබන්නේ කුමන අවස්ථාවලදීද?", "ශාන්තිකර්ම හා පෙරහැර අවස්ථාවලදී", "පාසල් විභාග ශාලාවලදී", "දහවල් කුඹුරු සීසෑමේදී", "නින්දට යන අවස්ථාවේදී", "පන්දම් දෙකක් හෝ කිහිපයක් දල්වාගෙන රාත්‍රී ශාන්තිකර්මවල ආලෝකය හා ආශිර්වාදය පතයි."),
        q("ශ්‍රී ලංකාවේ සම්ප්‍රදායික නර්තන ක්ෂේත්‍රයට නව ආලෝකයක් එක් කළ 'හේවුඩ්' ආයතනය වර්තමානයේ හඳුන්වන්නේ කුමන නමකින්ද?", "සෞන්දර්ය කලා විශ්වවිද්‍යාලය", "කොළඹ තාක්ෂණික විද්‍යාලය", "පේරාදෙණිය කලා පීඨය", "කැලණිය භාෂා පීඨය", "1946 දී ආරම්භ වූ රජයේ කලායතනය පසුව සෞන්දර්ය කලා විශ්වවිද්‍යාලය බවට පත් විය."),
        q("සම්ප්‍රදායික නැටුම් ශිල්පීන් තම පුහුණුව අතරතුර 'පාය' කියවීම හා 'පද' කටපාඩම් කිරීම සිදු කරන්නේ ඇයි?", "නැටුමේ තාල රටා හා පාද චලන මතකයේ තබා ගැනීමට", "අක්ෂර වින්‍යාසය වැරදවීමට", "කටහඬ වෙහෙසට පත් කිරීමට", "බෙර වාදනය නතර කිරීමට", "තත් තිත් තොං නං වැනි පද මාලා මඟින් බෙර හඬ හා නර්තන පියවර සම්බන්ධ කරයි."),
        q("උඩරට, පහතරට හා සබරගමු නර්තන සම්ප්‍රදායන්හිදී 'කවි කීම' නැටුමට අත්‍යවශ්‍ය වන්නේ ඇයි?", "කවියේ අර්ථය අභිනයෙන් හා නැටුමෙන් නිරූපණය කිරීමට", "ප්‍රේක්ෂකයන්ගේ කාලය නාස්ති කිරීමට", "වාද්‍ය භාණ්ඩ වසා තැබීමට", "නැට්ටුවන්ට විවේක ගැනීමට", "දේශීය නර්තනය ගායනය හා වාදනය සමඟ බැඳී පවතින ත්‍රිවිධ කලාවකි."),
        q("ශ්‍රී ලංකාවේ පැරණිම නාට්‍යමය ජන සම්ප්‍රදායක් වන 'සොකරි' කථා පුවත කුමන කලාපයක ප්‍රචලිත වී ඇත්ද?", "උඩරට හා සතර කෝරළේ ග්‍රාමීය ප්‍රදේශවල", "දකුණු මුහුදුබඩ වෙරළේ පමණි", "කොළඹ වරාය නගරයේ පමණි", "මන්නාරම දූපතේ පමණි", "කසී රටින් පැමිණි ගුරුහාමි හා සොකරිගේ පුවත වන්නි හා උඩරට කමත්වල රඟ දැක්වේ."),
        q("නර්තන කලාව තුළ 'ප්‍රවේණි උරුමය' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "පරම්පරාවෙන් පරම්පරාවට නර්තන ශිල්පය පවරා දීම", "විදේශීය බැලේ සම්ප්‍රදායන් අනුකරණය කිරීම", "නූතන වේදිකා ආලෝකකරණ ක්‍රම පුහුණු වීම", "තාලම්පට පමණක් භාවිතයෙන් නැටුම් සෑදීම", "නැටුම් ගුරුකුල රැකුණේ පියාගෙන් පුතාට හා ගුරුවරයාගෙන් ගෝලයාට ශිල්පය දීමෙනි."),
        q("පැරණි ලංකාවේ බෞද්ධ සිද්ධස්ථානවල බෙර වාදනය හා නැටුම් පැවැත්වීමේදී යොදා ගත් මූලික රිද්ම උපකරණ මොනවාද?", "දවුල, තම්මැට්ටම, හොරණෑව සහ තාලම්පට", "පියානෝව, වයලීනය සහ ගිටාරය", "සැක්සෆෝනය, ට්‍රම්පට් සහ ඩ්‍රම් සෙට්", "සිතාරය, තබ්ලාව සහ හාමෝනියම", "සාම්ප්‍රදායික හේවිසි කට්ටලය පංචතූර්ය වාදනයේ මූලික භාණ්ඩ වේ."),
        q("දේශීය ජන නැටුම් අතරින් 'කෘෂිකාර්මික ශ්‍රමය' සෘජුවම පිළිබිඹු නොවන නැටුම් අංගය කුමක්ද?", "රාජ සභා වන්නම් නැටුම", "ගොයම් නැටුම", "කුලු නැටුම", "වී පෙළීමේ නැටුම", "වන්නම් රාජ සභාවේ ගායනය හා රංගනය සඳහා නිර්මාණය වූ ශාස්ත්‍රීය අංගයකි."),
        q("ශ්‍රී ලංකාවේ විවිධ ප්‍රදේශ අනුව වෙනස් නොවන පොදු නර්තන ආචාර ධර්මය කුමක්ද?", "රංග භූමියට, ගුරුවරුන්ට හා වාද්‍ය භාණ්ඩවලට ගෞරව කිරීම", "පාවහන් පැළඳ බෙර මත හිඳගැනීම", "තාලය නොසලකා හිතුමතේ නැටීම", "අනෙක් ශිල්පීන්ට බාධා කිරීම", "සම්ප්‍රදාය කුමක් වුවද සෑම ශිල්පියෙකුම කලාවට හා භාණ්ඩවලට වඳිනු ලැබේ."),
        q("උඩරට නර්තන කලාවේ ඉහළම සම්මානනීය සළකුණ වන වෙස් තට්ටුව පැළඳීමට පෙර ශිල්පියා පුහුණු වන මූලික නැටුම් අංගය කුමක්ද?", "නෛයන්ඩි නැටුම", "සන්නි නැටුම", "කෝලම් නැටුම", "වඩිග පටුන", "ආධුනිකයෙකු වෙස් බැඳීමට පෙර සුදු උඩුකය ඇඳුමින් නෛයන්ඩි ඉදිරිපත් කරයි."),
        q("ගැමි උත්සවවලදී තරුණ තරුණියන් එක්ව ගයමින් නටන 'ඔන්චිලි වාරම්' හා බැඳුණු ජන සංස්කෘතික කාලසීමාව කුමක්ද?", "සිංහල අලුත් අවුරුදු සමය", "ඇසළ පොහොය සමය", "වප් මංගල්‍ය සමය", "දුරුතු පෙරහැර සමය", "බක් මහේ ඔන්චිලි පැදීම හා රබන් ගැසීම ශ්‍රී ලාංකේය ජන කලා උරුමයකි."),
        q("සිංහල ජන නැටුම්වල ඇඳුම් නිර්මාණයේදී භාවිත කරන සාම්ප්‍රදායික වර්ණ සංයෝජනය කුමක්ද?", "සුදු, රතු, කහ සහ නිල් වැනි දීප්තිමත් සරල වර්ණ", "කළු සහ අළු පමණි", "විනිවිද පෙනෙන නයිලෝන් රෙදි", "ලෝහමය රිදී පැහැති කබා", "ගැමි ඇඳුම් සරල බව, පිරිසිදු බව හා ප්‍රීතිමත් බව පෙන්වන වර්ණවලින් යුක්තය."),
        q("පැරණි ලංකාවේ කලා ශිල්පීන්ට 'රන් පට්ටම්' හෝ 'තාන්න මාන්න' ප්‍රදානය කිරීමෙන් රජු අපේක්ෂා කළේ කුමක්ද?", "දක්ෂ කලාකරුවන් දිරිමත් කිරීම හා කලාව රැකගැනීම", "කලා ශිල්පීන් පිටුවහල් කිරීම", "නැටුම් ප්‍රසංග තහනම් කිරීම", "වාද්‍ය භාණ්ඩ විනාශ කිරීම", "රාජ්‍ය අනුග්‍රහය ලැබීම නිසා පාරම්පරික කලාවන් ශතවර්ෂ ගණනාවක් නොනැසී පැවතිණි."),
        q("උඩරට සම්ප්‍රදායේ කලාකරුවෙකු සිය 'දැති පෝරුවේ' වැඳ නමස්කාර කරන්නේ කුමන ශාස්ත්‍රීය අවස්ථාවකදීද?", "වෙස් බැඳීමේ මංගල්‍යය හෙවත් ශීර්ෂාභරණ පැළඳීමේදී", "සොකරි නාටකය ආරම්භයේදී", "රබන් ක්‍රීඩාව අවසානයේදී", "ගොයම් කැපීමේදී", "මහනුවර පත්තිනි හෝ කතරගම දේවාලය වැනි පූජනීය ස්ථානවල වෙස් මංගල්‍යය පවත්වයි."),
        q("දේශීය නර්තනයේ 'ගායනය' හා 'වාදනය' අතර ඇති සම්බන්ධතාව කුමක්ද?", "නැටුමට අවශ්‍ය රිද්මය, කාලය හා භාවය ගායන-වාදන මගින් ගොඩනඟයි", "දෙකම එකිනෙකට කිසිදු සම්බන්ධයක් නැත", "ගායනය ඇති විට වාදනය සපුරා තහනම් වේ", "වාදනය ඇති විට නැට්ටුවා නිශ්චලව සිටී", "මනා නර්තන අත්දැකීමක් සඳහා නැටුම්, ගැයුම් සහ වැයුම් එකම ලයකින් බැඳිය යුතුය."),
        q("නර්තන ඉතිහාසයේදී 'කපිරිඤ්ඤා' ගීත හා නර්තන සඳහා භාවිත කළ ප්‍රධාන වාද්‍ය භාණ්ඩය කුමක්ද?", "රබාන හා වයලීනය", "ගැටබෙරය හා හොරණෑව", "යක් බෙරය හා තම්මැට්ටම", "උඩැක්කිය හා ගෙජ්ජි", "බටහිර ආභාසයෙන් ආ කපිරිඤ්ඤා නැටුමට ගිටාරය, මැන්ඩලීනය හා රබාන යොදා ගැනිණි."),
        q("දේශීය නර්තන සම්ප්‍රදායේ 'නාට්‍යමය ගුණය' වැඩි වශයෙන්ම දක්නට ලැබෙන්නේ කුමන අංගයන්හිද?", "කෝලම්, සොකරි හා දහඅට සන්නිය තුළ", "පා සරඹ අභ්‍යාස තුළ පමණි", "රබන් අත්ල තැබීම් තුළ පමණි", "තාලම්පට ගැසීමේදී පමණි", "චරිත නිරූපණය, දෙබස් හා හාස්‍ය රසය අන්තර්ගත වීම නිසා මේවා නාට්‍යමය වේ."),
        q("නවීන පාසල් නර්තන අධ්‍යාපනයේදී ප්‍රායෝගික පරීක්ෂණවලට අමතරව න්‍යායාත්මක දැනුම ඉගැන්වීමේ අරමුණ කුමක්ද?", "නර්තනයේ විද්‍යාත්මක, ඓතිහාසික හා ශාස්ත්‍රීය පදනම අවබෝධ කරවීම", "සිසුන්ට නැටුම් අමතක කරවීම", "වාද්‍ය භාණ්ඩ අලෙවිය වැඩි කිරීම", "විදේශ භාෂා ඉගැන්වීම", "ශිල්පය පමණක් නොව ඒ පිටුපස ඇති ඉතිහාසය, රස වින්දනය හා තාල ශාස්ත්‍රය දැනගත යුතුය."),
        q("ශ්‍රී ලංකාවේ පැරණි කලා ශිල්පීන්ගේ නම් අගට යෙදෙන 'පණී' හෝ 'ගණිත' වැනි ගෞරව කොටස්වලින් හැඟවෙන්නේ කුමක්ද?", "ඔවුන් සතු උසස් කලා හා ශාස්ත්‍රීය නිපුණතාව", "ඔවුන්ගේ ගමන් වේගය", "ඔවුන් වගා කළ භෝග වර්ග", "ඔවුන්ගේ උපන් දින", "ශිල්පීය දක්ෂතාව හා ප්‍රවීණත්වය අගය කරමින් මෙබඳු ගෞරව නාම පිරිනැමිණි."),
        q("පැරණි සිංහල ගැමි නැටුමක් වන 'තාලම් නැටුම' ඉදිරිපත් කිරීමේදී පදනම් කර ගන්නේ කුමක්ද?", "තාලම්පට හා ඊට අනුරූප වූ දෙපා හා අත් චලන", "රතු මුහුණු පැළඳීම", "උණ බට කණු මත නැගීම", "දිය යට කිමිදීම", "ලෝහ තාලම් යුගලයකින් ලැබෙන තියුණු නාදය තාලම් නැටුමේ රිද්මය මවයි."),
        q("පහතරට නර්තන ඉතිහාසයෙහි ලේඛනගත වී ඇති ප්‍රකට යාතුකර්ම කවි හා පෙළපාලි සංග්‍රහය කුමක්ද?", "දහඅට සන්නිය හා සූනියම් කවි පොත්", "සිදත් සඟරාව", "අමාවතුර", "බුත්සරණ", "පරම්පරාගත යකැදුරන් විසින් ශාන්තිකර්ම පෙළපාලි කවි ග්‍රන්ථාරූඪ කර රැකගෙන ඇත."),
        q("සබරගමු නර්තන කලාව ප්‍රවර්ධනය කිරීම සඳහා ප්‍රමුඛ මෙහෙයක් ඉටු කළ ප්‍රවීණ ගුරු පරම්පරාවක් කුමක්ද?", "රත්නපුර රතනජෝති හා මල්වල පරම්පරා", "අමුණුගම උඩරට පරම්පරාව", "අම්බලන්ගොඩ කෝලම් පරම්පරාව", "බෙන්තර තෙල්මේ පරම්පරාව", "සබරගමු ප්‍රදේශයේ පැරණි නර්තන ආචාර්යවරුන් දිගු දවුල හා පහිම්පත් සම්ප්‍රදාය රැකගත්හ."),
        q("මහනුවර පෙරහැරේ 'උඩැක්කි' සහ 'පන්තේරු' නැටුම් කණ්ඩායම් ඉටු කරන සෞන්දර්ය කාර්යය කුමක්ද?", "අතැති වාද්‍ය භාණ්ඩය වයමින් සමූහ නර්තනයේ යෙදීම", "පෙරහැරේ ඉදිරියෙන් ගමන් කරමින් හක්ගෙඩි හා කොම්බු පිඹීම", "අලි ඇතුන් ඉදිරියෙන් ගිනිබෝල කරකවමින් මඟ පෙන්වීම", "කස පිපිරවීම හා පන්දම් එළිය සැපයීම පමණක් ඉටු කිරීම", "මෙම උපකරණම වාද්‍ය භාණ්ඩයක් හා නර්තන ආභරණයක් ලෙස භාවිත වීම විශේෂත්වයකි."),
        q("ශ්‍රී ලංකාවේ ජන නැටුම්වල තාල ව්‍යුහය බොහෝ විට සකස් වී ඇත්තේ කුමන සරල පදනමකින්ද?", "ජන කවිවල සිව්පද විරිත හා කෙටි මාත්‍රා ඛණ්ඩ ඇසුරෙන්", "සංකීර්ණ සංස්කෘත ශ්ලෝක ඇසුරෙන්", "බටහිර ඔපෙරා ගායන ඇසුරෙන්", "ලතින් භාෂා ඡන්දස් ඇසුරෙන්", "ගැමියාට පහසුවෙන් ගායනා කොට රිද්මයට නැටිය හැකි සරල මාත්‍රා රටා මෙහි වේ."),
        q("ශාස්ත්‍රීය නර්තන අධ්‍යාපනයේදී 'ගුරු බුලත' දීමේ චාරිත්‍රයෙන් සංකේතවත් කෙරෙන්නේ කුමක්ද?", "ශිල්පය ඉගෙනීමට අවසර ගැනීම හා ගුරු ගෞරවය", "ප්‍රසංගය අවසානයේ වේදිකා තිරය වැසීම", "වන්නම් පරීක්ෂණ ලකුණු ප්‍රකාශයට පත් කිරීම", "පරණ වෙස්මුහුණු නැවත ගබඩාවේ තැන්පත් කිරීම", "සම්ප්‍රදායික කලා ශිල්පයක් ආරම්භ කිරීමේදී බුලත් හුරුල්ලක් පිළිගැන්වීම මංගල චාරිත්‍රයකි."),
        q("උඩරට නර්තන සම්ප්‍රදායේ 'වෙස්' නැටුම පැරණි කාලයේදී කාන්තාවන් විසින් ඉදිරිපත් නොකළේ ඇයි?", "එය කොහොඹා කංකාරියේ පුරුෂ පූජක පක්ෂයට වෙන් වූ පූජනීය ඇඳුමක් වූ බැවිනි", "කාන්තාවන්ට කිසිදු නැටුමක් තහනම් වූ බැවිනි", "වෙස් ඇඳුම ඉතා සැහැල්ලු වූ බැවිනි", "සංගීතය නොතිබුණු බැවිනි", "ශාන්තිකර්ම පිළිවෙත් හා චාරිත්‍ර අනුව වෙස් තට්ටුව පැළඳීම පිරිමි නැට්ටුවන්ට සීමා විය."),
        q("කලාවක් ලෙස නර්තනය පරිණාමය වීමේදී 'ප්‍රාථමික අභිචාරවල' සිට 'වේදිකා කලාව' දක්වා ගමන් කිරීමෙන් සිදු වූ වෙනස කුමක්ද?", "පූජා අරමුණට අමතරව රසාස්වාදය හා විනෝදය ප්‍රධාන වීම", "තාලය සම්පූර්ණයෙන් ඉවත් වීම", "ශාරීරික චලන නතර වීම", "ප්‍රේක්ෂකයන් ඉවත් කිරීම", "නූතන වේදිකාව තුළ ආලෝකකරණය, සංයෝජනය හා රසාස්වාදය ප්‍රමුඛත්වයට පත්ව ඇත."),
        q("උඩරට පහතරට හා සබරගමු නර්තන අංගයන්හිදී 'සභාවෙන් අවසර ගැනීම' සඳහා ගයන ආරම්භක කවි කුමක්ද?", "සභා වන්දනා කවි", "වියෝග කවි", "නැළවිලි ගී", "පැල් කවි", "ප්‍රේක්ෂක සභාවට හා විද්වතුන්ට ගෞරව කරමින් රංගනය ඇරඹීම පැරණි සම්ප්‍රදායයි."),
        q("ශ්‍රී ලංකාවේ පැරණි නර්තන කලාවට දකුණු ඉන්දීය ආභාසය වැඩි වශයෙන් ලැබුණු ඓතිහාසික යුගය කුමක්ද?", "පොළොන්නරු හා ගම්පොළ යුග", "ප්‍රාග් ඓතිහාසික ගල් යුගය", "බ්‍රිතාන්‍ය යුගයේ අවසානය", "ලන්දේසි යුගය", "පොළොන්නරුවේ ශිව දේවාල හා චෝල පාලන සමය තුළ දකුණු ඉන්දීය කලා ආභාසය ලැබිණි."),
        q("ඇම්බැක්කේ දේවාලයේ දැව කැටයම් අතර සුවිශේෂී නර්තන අංගයක් ලෙස කැටයම් කර ඇති කාන්තා නැටුම කුමක්ද?", "කළගෙඩි හා කෙණ්ඩි ගත් නළඟන රූප", "බැලේ නළඟන රූප", "කථක් නළඟන රූප", "ටැංගෝ නර්තන රූප", "ගම්පොළ යුගයේ දැව කැටයම් එකල සමාජයේ ජනප්‍රිය වූ නැටුම් පෙන්වයි."),
        q("පැරණි සිංහල රජවරුන් විසින් විහාර දේවාලවල නැටුම් පවත්වාගෙන යාමට පත් කළ ප්‍රධාන නිලධාරියා කවුද?", "බස්නායක නිලමේ හෝ දියවඩන නිලමේ", "කෝරාළ හෝ විදානේ ආරච්චි", "මහ අදිකාරම් හෝ දිසාවේ", "ගම් මුලාදෑනි හෝ ආරච්චිල", "දේවාල හා දළදා මාලිගාවේ පෙරහැර සහ තේවා කටයුතු මෙම නිලමේවරුන් යටතේ පාලනය විය."),
        q("මහනුවර යුගයේ 'වන්නම්' ප්‍රචලිත වීමට රාජකීය අනුග්‍රහය දැක්වූ රජතුමා කවුද?", "ශ්‍රී වීර පරාක්‍රම නරේන්ද්‍රසිංහ රජු", "අනුරාධපුර යුගයේ ධාතුසේන මහ රජතුමා", "සීගිරි රාජධානියේ පළමුවන කාශ්‍යප රජතුමා", "පොළොන්නරු යුගයේ මහා පරාක්‍රමබාහු රජතුමා", "කුණ්ඩසාලේ රාජධානියේදී නරේන්ද්‍රසිංහ රජුගේ කවිකාර මඩුව වන්නම් සඳහා ප්‍රසිද්ධ විය."),
        q("ජන නැටුම් අතරින් 'කාන්තාවන්' පමණක් ප්‍රධාන වශයෙන් ඉදිරිපත් කරන ගැමි නැටුම් යුගලය කුමක්ද?", "කළගෙඩි නැටුම සහ කුලු නැටුම", "වඩිග පටුන සහ කස නැටුම", "ගිනි පෑගීම සහ ලී කෙළි", "වෙස් නැටුම සහ කෝලම්", "ගැමි කාන්තාවන්ගේ ජලය ගෙන ඒම හා වී පෙළීම මෙම නැටුම්වලට පදනම් වේ."),
        q("ලී කෙළි නැටුමේදී නැට්ටුවන් අතේ තබා ගන්නා ලී කෝටු සෑදීමට වඩාත් සුදුසු ශාක දැවය කුමක්ද?", "කළුවර, කිතුල් හෝ අලුබෝ වැනි සවිමත් දැව", "කෙසෙල් කඳ", "පැපොල් අතු", "වට්ටක්කා වැල්", "එකිනෙක ගැටෙන විට හොඳ නාදයක් හා කල්පැවැත්මක් ලැබෙන ශක්තිමත් දැව යොදා ගනී."),
        q("ගොයම් නැටුමේදී ගායනා කරන කවිවල ප්‍රධාන තේමාව වන්නේ කුමක්ද?", "සශ්‍රීක අස්වැන්නක් පැතීම හා ගොවි ශ්‍රමය වර්ණනා කිරීම", "මුහුදු යාත්‍රා කිරීම හා ධීවර ජීවිතය වර්ණනා කිරීම", "රාජ සභාවේ විනිශ්චය හා යුද ජයග්‍රහණ වර්ණනා කිරීම", "කඩු හා දඬු හරඹ පුහුණුවේ ශක්තිය වර්ණනා කිරීම", "වැපිරීමේ සිට ගොයම් කැපීම දක්වා ගොවි ජීවිතය මෙම කවිවල ඇතුළත් වේ."),
        q("පොල් කටු නැටුමේදී භාවිත කරන පොල් කටු යුගලය සකසා ගන්නා ආකාරය කුමක්ද?", "පිරිසිදු කර මැද සිනිඳු කර තාල නාද නැඟෙන සේ සැකසීම", "වැලි පුරවා ගැටගැසීම", "යකඩ ඇණ ගසා සවි කිරීම", "කඩදාසිවලින් එතීම", "මුවින මුව ගැටීමෙන් පැහැදිලි රිද්ම හඬක් නැඟෙන පරිදි පොල් කටු පිරිසිදු කෙරේ."),
        q("සිංහල ජන සංගීතයේ හා ජන නැටුම්වල 'රබන් පද' නිර්මාණය වී ඇත්තේ කුමන ශබ්ද අනුසාරයෙන්ද?", "එදිනෙදා පරිසරයේ සිදුවීම්, සතුන් හා හාස්‍ය රසය", "හින්දුස්ථානි රාගධාරී ශාස්ත්‍රීය ස්වර ප්‍රස්තාර", "පහතරට සන්නි මන්ත්‍ර හා යාතිකා පදමාලා", "භාරතීය හස්ත මුද්‍රා ශ්ලෝක හා සූත්‍ර පාඨ", "ගැමි ජනතාවගේ නිර්මාණශීලී රිද්මය හා උපහාසය රබන් පදවල රැඳී පවතී."),
        q("දේශීය නර්තන කලාවේදී 'මුහුදුබඩ පහතරට' ප්‍රදේශවල ව්‍යාප්ත වූ වෙස්මුහුණු නාටක සම්ප්‍රදාය කුමක්ද?", "කෝලම් නැටුම් සම්ප්‍රදාය", "සොකරි නැටුම් සම්ප්‍රදාය", "කොහොඹා කංකාරිය", "කළගෙඩි නැටුම", "දකුණු මුහුදුබඩ අම්බලන්ගොඩ, මිරිස්ස හා බෙන්තර ආශ්‍රිතව කෝලම් ප්‍රචලිත විය."),
        q("උඩරට නැටුමේ 'පන්තේරු' නැටුම ඉදිරිපත් කිරීමේදී නැට්ටුවන් සමූහයක් අනුගමනය කරන රටාව කුමක්ද?", "වෘත්තාකාර හා සමාන්තර පෙළ රටා ඔස්සේ හුවමාරු වීම", "එකම තැන හිඳගෙන සිටීම", "වේදිකාවෙන් ඉවතට හැරී සිටීම", "වෙන වෙනම කතා කරමින් සිටීම", "පන්තේරු කරකවමින් එකිනෙකා අතර මාරු වීමේ දර්ශනීය රටා මෙහි වේ."),
        q("ශ්‍රී ලංකාවේ නර්තනයට සුවිශේෂී සේවාවක් කළ පණීභාරත මහතා විසින් නිර්මාණය කරන ලද ප්‍රසිද්ධ මුද්‍රා නාට්‍යයක් කුමක්ද?", "සැළලිහිණි හෝ නළඟන", "හැම්ලට්", "රෝමියෝ ජුලියට්", "ඔතෙලෝ", "පණීභාරත මහතා දේශීය ශෛලියෙන් බැලේ සහ වේදිකා නර්තන නිර්මාණ රැසක් බිහි කළේය."),
        q("මහාචාර්ය චිත්‍රසේනයන් විසින් දේශීය නර්තනය ඇසුරෙන් නිර්මාණය කළ ලෝක ප්‍රකට මුද්‍රා නාට්‍යය කුමක්ද?", "කරදිය", "මැක්බත්", "මහාසාර", "හුණුවටයේ කතාව", "ධීවර ජීවිතය පාදක කර ගනිමින් දේශීය නර්තන රටා ඇසුරෙන් 'කරදිය' නිර්මාණය විය."),
        q("නර්තන ඉතිහාසයේදී 'පහන් මඩුව' යනු කුමන සම්ප්‍රදායට අයත් ප්‍රධාන පූජා උත්සවයක්ද?", "සබරගමු හා පහතරට දේව ශාන්තිකර්ම සම්ප්‍රදායට", "උඩරට රාජ සභා වන්නම් සම්ප්‍රදායට", "බටහිර බැලේ සම්ප්‍රදායට", "උතුරු ඉන්දීය කථක් සම්ප්‍රදායට", "පත්තිනි දේවිය ප්‍රධාන දේව මණ්ඩලය පිදීම උදෙසා පහන් මඩු පැවැත්වේ."),
        q("පැරණි ශ්‍රී ලංකාවේ 'තූර්ය වාදකයන්' රජුගේ සවාරි හා යුද ගමන්වලදී ඉදිරියෙන් ගමන් කළේ කුමන බෙර රැගෙනද?", "රණ බෙර හෙවත් මහා බෙර", "අත් රබාන", "උඩැක්කිය", "තබ්ලාව", "සෙබළුන්ට ධෛර්යය ලබා දීමට හා රජුගේ ගමන දැනුම් දීමට රණ බෙර හා හේවිසි වයන ලදී."),
        q("නර්තන ඉතිහාසයේදී සාම්ප්‍රදායික ගැමි නැටුම්වල 'සමූහ ගායනය' වැදගත් වන්නේ ඇයි?", "සියලු දෙනා අතර ඒකාබද්ධ රිද්මයක් හා ප්‍රබෝධයක් ඇති කිරීමට", "නැටුම ඉක්මනින් නතර කිරීමට", "ප්‍රේක්ෂකයන් පළවා හැරීමට", "වාද්‍ය භාණ්ඩ අමතක කිරීමට", "එක් අයෙකු ගයන කවි පදය සෙසු පිරිස පුනරුච්චාරණය කිරීම ගැමි නැටුමේ ලක්ෂණයකි."),
        q("දේශීය නර්තන ක්ෂේත්‍රයේදී 'ශාන්තිකර්ම පෙළපාලි' යනුවෙන් හඳුන්වන්නේ කුමක්ද?", "ප්‍රධාන ශාන්තිකර්මය අතරතුර ක්‍රමවත්ව ඉදිරිපත් කරන නර්තන හා නාට්‍ය අංග", "ඇසළ පෙරහැර අවසානයේ සියලු පිරිස නිහඬව විසිර යාමේ අවස්ථාව", "යාගයට පෙර නැටුම් ශාලාව කහ දියර ඉස සේදීමේ පවිත්‍ර කටයුත්ත", "මල් බුලත් තටුව සඳහා පූජා රෙදිපිළි සකස් කර තබා ගැනීම", "පන්දම් පාලිය, කෙණ්ඩි පාලිය, සළු පාලිය ආදිය මෙම පෙළපාලිවලට අයත් වේ."),
        q("ශ්‍රී ලංකාවේ 'චාරිත්‍රමය නැටුම්' යන කාණ්ඩයට ඇතුළත් කළ හැකි ප්‍රධාන නර්තන අංගය කුමක්ද?", "දේවාල හා විහාරස්ථානවල පවත්වන තේවා නැටුම්", "වේදිකා නාට්‍ය විකට නැටුම්", "සිනමා ගීත නැටුම්", "විදේශීය සාද නැටුම්", "නියමිත දින වකවානුවලදී ආගමික හෝ සංස්කෘතික චාරිත්‍රයක් ලෙස ඉටු කරන නැටුම් මෙයට අයත් වේ."),
        q("උඩරට නැටුම් කලාවේදී 'නරේන්ද්‍රසිංහ රජු' සමයේ සිදු වූ වැදගත්ම ප්‍රගතිය කුමක්ද?", "දහඅට වන්නම් රචනා වීම හා රාජ්‍ය සභාවේ ගායනා කිරීම", "යක් බෙරය තහනම් කිරීම", "පහතරට සන්නි ආරම්භ කිරීම", "වෙස්මුහුණු කැපීම නතර කිරීම", "කුණ්ඩසාලේ කවිකාර මඩුව මගින් උඩරට වන්නම් කවි සාහිත්‍යය පෝෂණය විය."),
        q("ශ්‍රී ලංකාවේ ජන නැටුම් අතර 'පොල් නැටුම' හෝ 'පොල් කටු නැටුම' වැඩි වශයෙන් නිරූපණය කරන්නේ කුමක්ද?", "පොල් වගාව හා ගැමි ජීවිතයේ විනෝදාංශ", "රාජ්‍ය තාන්ත්‍රික සබඳතා", "රන් ආභරණ නිෂ්පාදනය", "මැටි වළං තැනීම", "ගැමි කාන්තාවන් හා තරුණයන්ගේ විවේක කාලීන ක්‍රීඩාශීලී රිද්මය මෙයින් දිස්වේ."),
        q("දේශීය නර්තන සම්ප්‍රදායන් අතරින් 'බෙන්තර', 'මාතර' සහ 'රයිගම' යනු කුමන සම්ප්‍රදායේ උප කලාපද?", "පහතරට නර්තන සම්ප්‍රදායේ", "උඩරට නර්තන සම්ප්‍රදායේ", "සබරගමු නර්තන සම්ප්‍රදායේ", "භරත නාට්‍යම් සම්ප්‍රදායේ", "ප්‍රාදේශීය උච්චාරණය, තාල රටා හා පෙළපාලි වෙනස්කම් මත මෙම පහතරට ගුරුකුල බෙදී ඇත."),
        q("සබරගමු නර්තන සම්ප්‍රදායට අයත් නොවන ලක්ෂණය කුමක්ද?", "යක් බෙරය ප්‍රධාන වාද්‍ය භාණ්ඩය ලෙස භාවිත කිරීම", "දිගු දවුල ප්‍රධාන බෙරය වීම", "සමන් දෙවියන් මුල් කරගත් පහන් මඩු පැවැත්වීම", "පහිම්පත් ඇඳුම භාවිත කිරීම", "සබරගමු සම්ප්‍රදායේ ප්‍රධාන බෙරය දිගු දවුල වන අතර යක් බෙරය පහතරටට අයත් වේ."),
        q("පැරණි ලංකාවේ 'රාජකාරි ක්‍රමය' නර්තන කලාවේ පැවැත්මට උපකාරී වූයේ කෙසේද?", "විහාර හා දේවාල ඉඩම් භුක්ති විඳිමින් නොකඩවා කලා සේවාව ඉටු කිරීමට ඉඩ සැලසීමෙන්", "කලාකරුවන්ට සෑම වසරකම රාජ සභාවෙන් නීතිමය දඬුවම් නියම කිරීමෙන්", "පන්සල් හා දේවාල සතු සියලු පැරණි බෙර වාද්‍ය භාණ්ඩ විනාශ කර දැමීමෙන්", "වාර්ෂික ඇසළ හා දේවාල පෙරහැරවල් සියල්ල සම්පූර්ණයෙන්ම නතර කිරීමෙන්", "පරම්පරාගත ඉඩම් උරුමය කලා ශිල්පය නොනැසී පවත්වා ගැනීමට දායක විය."),
        q("උඩරට නර්තනයේ 'සවරම් නැටුම' ඉදිරිපත් කිරීමේදී නැට්ටුවන්ගේ අත්වල තබා ගන්නා 'සවරම' සාදා ඇත්තේ කුමකින්ද?", "වර්ණවත් රෙදි පටි හෝ කෙඳි ගැටගැසූ දණ්ඩකින්", "මුවහත් තලයකින් යුත් කෙටි ලෝහ කඩුවකින්", "පිළිස්සූ සැහැල්ලු රතු මැටි කළගෙඩියකින්", "වේවැල්වලින් වියූ පැතලි ජන කුල්ලකින්", "සවරම කරකැවීමේදී හා විසි කිරීමේදී අලංකාර වර්ණ රටා දැකගත හැකිය."),
        q("ශ්‍රී ලංකාවේ පැවැත්වෙන 'දේව පූජා නැටුම්' සම්බන්ධයෙන් නිවැරදි ප්‍රකාශය කුමක්ද?", "දෙවියන්ගේ ආශිර්වාදය හා රෝග නිවාරණය පතා ඉදිරිපත් කරයි", "සතුන් දඩයම් කිරීම සඳහා පමණක් නටයි", "කිසිදු ගෞරවයකින් තොරව නටයි", "වාද්‍ය භාණ්ඩ තහනම් කර නටයි", "විෂ්ණු, කතරගම, සමන් හා පත්තිනි දෙවිවරුන් පිදීම දේශීය නැටුමේ වැදගත් කොටසකි."),
        q("ජන නැටුම් පුහුණු වීමෙන් කුඩා දරුවන් තුළ වර්ධනය වන ප්‍රධානම ශාරීරික හැකියාව කුමක්ද?", "රිද්මයානුකූල චලන සම්බන්ධීකරණය හා නම්‍යශීලී බව", "වැඩි වේලාවක් නිදා ගැනීම", "ඇස් පෙනීම දුර්වල වීම", "කතා නොකර සිටීම", "අත්, පා සහ හිස තාලයට ගැළපීම දරුවන්ගේ චාලක කුසලතා දියුණු කරයි."),
        q("ගැමි සමාජයේදී 'තාලම් කවි' ගායනා කරමින් ඉදිරිපත් කරන නර්තන අංගයේ ඇති විශේෂත්වය කුමක්ද?", "සියලු ශිල්පීන් අතේ තාලම්පට බැගින් රැගෙන තාල අල්ලමින් නැටීම", "බෙර වාදකයෙකු කිසිසේත්ම නොසිටීම", "මුහුණු ආවරණ පැළඳ සිටීම", "දිය යට නැටීම", "තාලම් නාදය මූලික කරගත් විවිධ වට රටා මෙම නැටුමේ අන්තර්ගත වේ."),
        q("උඩරට නැටුම් ක්ෂේත්‍රයේ 'ගුරු කුල' බිහිවීමට බලපෑ ප්‍රධානම සාධකය කුමක්ද?", "එක් එක් ප්‍රදේශයේ පාරම්පරික ආචාර්යවරුන්ගේ ආවේණික ශෛලීන්", "රජයේ පාසල් පෙළපොත් හා විෂය මාලාව", "විදේශීය සංචාරක රංග කලා නාළිකා", "නවීන කවි පොත් මුද්‍රණ සමාගම්", "ගුරු පරම්පරා අනුව තාල පද හා ශරීර චලනවල සියුම් අනන්‍යතා බිහි විය."),
        q("නර්තන ඉතිහාසයේදී 'පහතරට නර්තනය' හඳුන්වන තවත් ප්‍රකට නාමයක් කුමක්ද?", "රුහුණු නර්තන සම්ප්‍රදාය", "මායා නර්තන සම්ප්‍රදාය", "පිහිටි නර්තන සම්ප්‍රදාය", "කඳුරට නර්තන සම්ප්‍රදාය", "දකුණු ලංකාව හෙවත් රුහුණු රටේ ව්‍යාප්ත වූ බැවින් රුහුණු නැටුම් ලෙසද හැඳින්වේ."),
        q("සම්ප්‍රදායික නර්තන කලාවේදී 'මල් යහන් කවි' ගායනා කරනු ලබන්නේ කුමන කාර්යය සඳහාද?", "දෙවියන්ට මල් ආසනය වෙත වැඩමවන ලෙස ආරාධනා කිරීමට", "නැට්ටුවන් නින්දට යැවීමට", "වේදිකාව ගලවා දැමීමට", "අස්වැන්න කිරා මැනීමට", "ශාන්තිකර්ම මඩුවේ සකස් කළ මල් යහනාවට දෙවියන් ආරාධනා කිරීමට මෙය ගැයේ."),
        q("නූතන වේදිකා නර්තනයේදී සාම්ප්‍රදායික නැටුමක් ඉදිරිපත් කිරීමේදී අවධානය යොමු කළ යුතු ප්‍රධාන සීමාව කුමක්ද?", "සම්ප්‍රදායේ මූලික ශාස්ත්‍රීය අනන්‍යතාව විකෘති නොකර ගැනීම", "කිසිදු වර්ණ ආලෝකයක් නොදැමීම", "ප්‍රේක්ෂකයන්ට ආසන නොදීම", "වාද්‍ය භාණ්ඩ වේදිකාවෙන් ඉවත් කිරීම", "නව නිර්මාණකරණයේදී පවා මූලික ශෛලිය හා ගෞරවය සුරැකිය යුතුය."),
        q("දේශීය නර්තන ඉතිහාසයේ සඳහන් වන 'දිග්ගේ නැටුම' ප්‍රධාන වශයෙන් පැවැත්වූයේ කුමන ස්ථානවලද?", "පුරාණ දේවාලවල පිහිටි දිගු ශාලා හෙවත් දිග්ගේ තුළ", "මුහුදු වෙරළේ බෝට්ටු තුළ", "ගොවි කමත්වල රාත්‍රියේ", "පාසල් ක්‍රීඩා පිටිවල", "මහ සමන් දේවාලය හා ඇම්බැක්කේ වැනි දේවාලවල දිග්ගේ නැටුම් පැවති බව සඳහන් වේ."),
        q("ශ්‍රී ලංකාවේ නර්තන කලාවට අමතරව 'චිත්‍ර හා මූර්ති' කලාවන්ගෙන් හඳුනාගත හැකි නර්තන සාධක මොනවාද?", "සඳකඩපහණ, විහාර බිතුසිතුවම් හා දැව කැටයම්වල නළඟන රූප", "නූතන ප්‍රසංග වේදිකා තිර සැරසිලි හා පෝස්ටර් චිත්‍ර", "පැරණි ලෝහ කාසිවල ඇති රාජ්‍ය මුද්‍රා සටහන්", "නවීන පාසල් පෙළපොත්වල රේඛාමය සටහන් පමණි", "කැලණිය, දඹුල්ල හා මහනුවර විහාර සිතුවම්වල පැරණි වාද්‍ය භාණ්ඩ හා නැටුම් දැකගත හැකිය."),
        q("ගැමි ජන නැටුම් අතරින් 'කෘෂිකාර්මික නොවන' ජීවනෝපායන් ඇසුරෙන් නිර්මාණය වූ නැටුමකට නිදසුනක් කුමක්ද?", "ධීවර නැටුම හෝ මල් නැටුම", "ගොයම් නැටුම", "කුලු නැටුම", "වී පෙළීමේ නැටුම", "මුහුදු රැකියාවේ යෙදෙන ධීවර ජනතාවගේ දැල් ඇදීම හා ඔරු පැදීම ඇසුරෙන් නව ජන නැටුම් සැකසී ඇත."),
        q("උඩරට නැටුමේ 'පන්තේරු' නැටුම හා 'උඩැක්කි' නැටුම අතර පවතින පොදු ලක්ෂණය කුමක්ද?", "දෙකෙහිම නැට්ටුවා අතැති උපකරණයම වාදනය කරමින් නැටීම", "දෙකෙහිම කෝලම් වෙස්මුහුණු පැළඳීම", "දෙකෙහිම කිසිදු තාලයක් නොමැති වීම", "දෙකෙහිම වෙස් තට්ටුව පැළඳීම", "උඩැක්කිය හා පන්තේරුව අතේ තබා වයමින් නැටිය යුතු උඩරට නර්තන අංග දෙකකි."),
        q("පහතරට නර්තන සම්ප්‍රදායේ ආරම්භය හා බැඳුණු ප්‍රකට පුරාවෘත්තය කුමන දේවිය හෝ චරිතය වටා ගෙතී ඇත්ද?", "විසාලා මහනුවර තුන්බිය හා රිද්දි බිසවුන් වැනි කතා පුවත්", "මහනුවර මලය රජුගේ කතාව", "සොකරි කසී රට කතාව", "අලිබාබා සහ හොරු හතළිහ", "දහඅට සන්නිය හා රට යකුම වැනි පහතරට යාගවලට ඉපැරණි බෞද්ධ හා ජනශ්‍රැති පුවත් මුල් වී ඇත."),
        q("සාම්ප්‍රදායික නර්තන පුහුණුවේදී ශිෂ්‍යයා 'නම්‍යශීලී ව්‍යායාම' මුලින්ම සිදු කළ යුත්තේ ඇයි?", "පේශි හා සන්ධි ආබාධ වළක්වා මණ්ඩි හා කැරකිලි පහසු කිරීමට", "වේදිකා අවකාශය මැන බලා ස්ථාන සලකුණු කර ගැනීමට", "කවි ගායනය සඳහා කටහඬ උච්ච ස්වරයට පුහුණු කිරීමට", "රංග වස්ත්‍ර හා ආභරණවල සමබරතාව පරීක්ෂා කිරීමට", "උණුසුම් වීමේ ව්‍යායාම මගින් දණහිස් හා ඉණ ආබාධවලින් තොරව නැටීමට මඟ සැලසේ."),
        q("ශ්‍රී ලංකාවේ 'සබරගමු නර්තනය' ආරක්ෂා වීමට ප්‍රධාන වශයෙන්ම හේතු වූ ආගමික මධ්‍යස්ථානය කුමක්ද?", "රත්නපුර මහ සමන් දේවාලය", "කැලණි රජමහා විහාරය", "නල්ලූර් කෝවිල", "මිහින්තලය විහාරය", "මහ සමන් දේවාලයේ පෙරහැර හා පහන් මඩු සබරගමු නර්තනයේ ජීව ගුණය රැකගත්තේය."),
        q("නර්තන කලාවේදී 'ස්වභාවික අනුකරණය' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "සතුන්ගේ ගමන්, සුළඟ හා ගහකොළ චලන නැටුමෙන් දැක්වීම", "වේදිකා පසුතලයේ වර්ණ තිර රෙදි පමණක් වෙනස් කිරීම", "පැරණි කවි පොත්වල අක්ෂර නැවත පිටපත් කර ගැනීම", "බෙර වාදනය නතර කර මුඛයෙන් හඬ අනුකරණය කිරීම", "මොනරා, ඇතා, උකුස්සා වැනි සතුන්ගේ ඉරියව් වන්නම් හා ජන නැටුම්වලට පාදක විය."),
        q("ශ්‍රී ලංකාවේ සම්ප්‍රදායික නර්තනයේ 'ගාම්භීරත්වය' වැඩි වශයෙන්ම ඉස්මතු වන නැටුම් අංගය කුමක්ද?", "උඩරට වෙස් නැටුම", "කෝලම් විකට නැටුම", "පොල් කටු නැටුම", "රබන් කරකැවීම", "වෙස් තට්ටුව, පළල් මණ්ඩිය සහ ගැටබෙර නාදය එක්ව රාජකීය ගාම්භීරත්වයක් මවයි."),
        q("දේශීය නර්තන අධ්‍යාපනයේදී 'ප්‍රායෝගික හා න්‍යායාත්මක සමතුලිතතාව' රැකගැනීමෙන් අපේක්ෂා කරන්නේ කුමක්ද?", "නිපුණ නැට්ටුවෙකු මෙන්ම කලාව ගැන විද්වත් දැනුමක් ඇති ශිල්පියෙකු බිහි කිරීම", "සම්ප්‍රදායික ප්‍රායෝගික නැටුම් අත්හැර දැමීම", "න්‍යායාත්මක දැනුම සම්පූර්ණයෙන් ඉවත් කිරීම", "ශාස්ත්‍රීය කලා පොත් ඉවත දැමීම", "විෂය දැනුම හා ප්‍රායෝගික කුසලතා දෙකම සම්පූර්ණ නර්තනවේදියෙකුට අවශ්‍ය වේ."),
        q("සිංහල නර්තන සාහිත්‍යයේදී 'තාල ශාස්ත්‍රය' යනුවෙන් හැඳින්වෙන්නේ කුමන විෂය ක්ෂේත්‍රයද?", "නැටුමේ හා වාදනයේ කාල මිනුම්, මාත්‍රා හා ලය පිළිබඳ විද්‍යාව", "රංග වස්ත්‍ර මසන රෙදි වර්ග පිළිබඳ දැනුම", "වේදිකා විදුලි පහන් සවි කිරීම", "වෙස්මුහුණු සායම් තේරීම", "තාලය සහ ලය නිවැරදිව පිහිටුවීම නර්තනයේ කොඳු නාරටිය බඳුය."),
        q("ශ්‍රී ලංකාවේ නර්තන උරුමය රැකගැනීම සඳහා පාසල් මට්ටමින් සිදු කළ හැකි වඩාත්ම ප්‍රායෝගික ක්‍රියාමාර්ගය කුමක්ද?", "නිවැරදි සම්ප්‍රදායික ශෛලියෙන් නර්තනය හදාරා ප්‍රාසාංගිකව ඉදිරිපත් කිරීම", "පැරණි බෙර වාද්‍ය භාණ්ඩ භාවිතයෙන් ඉවත් කිරීම", "විදේශීය නැටුම් පමණක් පුහුණු වීම", "කවි හා වන්නම් කටපාඩම් කිරීම නතර කිරීම", "නව පරපුර සම්ප්‍රදායික නර්තනය ආදරයෙන් ප්‍රගුණ කිරීමෙන් එය සදාකාලිකව රැකේ.")
    )
}

